import matplotlib.pyplot as pltimport rasterioimport rasterio.windowsclass MNT:    def __init__(self, filename, wdir):        self.path = wdir + filename        self.raster = rasterio.open(self.path)    def elevations(self, coord):        elevations = []        for pt in coord:            lig, col = self.raster.index(pt[0], pt[1])            window = rasterio.windows.Window(col, lig, 1, 1)            try:                elevation = self.raster.read(1, window=window)[0, 0]            except IndexError:                elevations.append("NaN")                continue            elevations.append(elevation)        return elevations    def print(self, abs, elevations):        plt.plot(abs, elevations, "k")